def query_arrow(
    ctx: RequestContext,
    name: str,
    query: Query,
) -> List[RecordBatch]:
    """Query the registry as the caller: the Query's bound sources name the registry's tables; rows are the newest per key and filtered by the objects' ACLs. Apache Arrow IPC stream out.

    Arguments:
    ctx: RequestContext -- A request context object
    name: str -- The registry's name (e.g. `models`)
    query: Query -- The query to execute; its table sources are registry table names

    Returns:
    The rows the caller may see
    """

    path = "/v1/api/ulv2/registry/:name/query"
    path = path.replace(":name", str(name), 1)

    params = dict()
    headers = dict()
    headers["accept"] = "application/vnd.apache.arrow.stream";

    body = query.to_bytes()
    res = ctx.post(path, body=body, mimetype="application/octet-stream", params=params, headers=headers)
    reader = RecordBatchStreamReader(res)
    return reader.read_all().to_batches()
